/* ---------- SVG diagram library: hand-built instructional plates ---------- */
function mdefs(p){
  return '<defs>'+
  '<marker id="'+p+'-b" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="#3fb0ff"/></marker>'+
  '<marker id="'+p+'-r" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="#ff5a2e"/></marker>'+
  '<marker id="'+p+'-o" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="#ff8c42"/></marker>'+
  '<marker id="'+p+'-g" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="#9fb3a8"/></marker>'+
  '<pattern id="'+p+'-h" width="9" height="9" patternTransform="rotate(45)" patternUnits="userSpaceOnUse"><rect width="9" height="9" fill="rgba(255,90,46,0.10)"/><line x1="0" y1="0" x2="0" y2="9" stroke="#ff5a2e" stroke-width="2.5"/></pattern>'+
  '</defs>';
}
function FLAME(x,y,s){
  return '<g transform="translate('+x+' '+y+') scale('+s+')">'
    +'<path d="M0 0 C -12 -8 -10 -22 0 -34 C 10 -22 12 -8 0 0 Z" fill="#ff7a2e"/>'
    +'<path d="M0 -2 C -5 -8 -4 -17 0 -23 C 4 -17 5 -8 0 -2 Z" fill="#ffd166"/></g>';
}
function FIG(x,y,s,opts){
  opts = opts||{};
  var mask = opts.mask?'<rect x="-4.5" y="-61.5" width="9" height="7" rx="2.5" fill="#3a352e"/>':'';
  var scba = opts.scba?'<rect x="-9.5" y="-52" width="6" height="28" rx="3" fill="#7a6f5c"/><circle cx="-6.5" cy="-46" r="2.6" fill="#9fb3a8"/>':'';
  return '<g transform="translate('+x+' '+y+') scale('+s+')">'
    + scba
    +'<rect x="-5.5" y="-28" width="4.6" height="28" rx="2.2" fill="#cfc3ae"/>'
    +'<rect x="0.9" y="-28" width="4.6" height="28" rx="2.2" fill="#cfc3ae"/>'
    +'<rect x="-10.8" y="-52" width="4" height="21" rx="2" fill="#c3b69e"/>'
    +'<rect x="6.8" y="-52" width="4" height="21" rx="2" fill="#c3b69e"/>'
    +'<rect x="-6.5" y="-54" width="13" height="29" rx="4.5" fill="#cfc3ae"/>'
    +'<circle cx="0" cy="-60" r="5.4" fill="#d8cdb8"/>'
    + mask
    +'<rect x="-9" y="-67" width="18" height="3" rx="1.5" fill="#e2d9c6"/>'
    +'<path d="M-5.6 -67 A5.6 5.6 0 0 1 5.6 -67 Z" fill="#e2d9c6"/></g>';
}
function wallPath(x1,y1,x2,y2){ return '<line x1="'+x1+'" y1="'+y1+'" x2="'+x2+'" y2="'+y2+'" stroke="#d9cfb8" stroke-width="4"/>'; }

